I checked multiple possible approaches to serializing. The main goal was to pick one considering compression efficiency, time to encode, and time to decode. The candidates:

* MessagePack. Binary serializing protocol [https://en.wikipedia.org/wiki/MessagePack|https://en.wikipedia.org/wiki/MessagePack|smart-link] 
* lz4. The compression algorithm that we are already using in the backend. [https://en.wikipedia.org/wiki/LZ4_(compression_algorithm)|https://en.wikipedia.org/wiki/LZ4_(compression_algorithm)|smart-link] 
* Protobuf. Serialization protocol [https://en.wikipedia.org/wiki/Protocol_Buffers|https://en.wikipedia.org/wiki/Protocol_Buffers|smart-link] 
* Zlib. Data compression library built into NodeJS. Here, we're interested in `deflate`, `broatli` and `gzip`.
* BSON. Binary serialization format

To test them all, I wrote a small benchmark that simulates the encoding/decoding of an array of 30 cache entries 10_000 times. Here's the result:

{noformat}┌─────────┬───────────────────────┬──────────────┬───────────────────────┬───────────────────────┐
│ (index) │ Method                │ Size (bytes) │ Pack time (ns)        │ Unpack time (ns)      │
├─────────┼───────────────────────┼──────────────┼───────────────────────┼───────────────────────┤
│ 0       │ 'JSON.strigify'       │ 2461         │ '0        - 0       ' │ '7459     - 241833  ' │
│ 1       │ 'MessagePack'         │ 1503         │ '4167     - 364375  ' │ '9708     - 632333  ' │
│ 2       │ 'JSON + LZ4'          │ 243          │ '2500     - 4105625 ' │ '21084    - 10902500' │
│ 3       │ 'JSON + zlib.deflate' │ 158          │ '10333    - 1212375 ' │ '10417    - 1748459 ' │
│ 4       │ 'JSON + zlib.gzip'    │ 170          │ '10416    - 622083  ' │ '10375    - 923917  ' │
│ 5       │ 'JSON + zlib.broatli' │ 136          │ '2701625  - 12778917' │ '11792    - 429625  ' │
└─────────┴───────────────────────┴──────────────┴───────────────────────┴───────────────────────┘
{noformat}

# BSON threw an exception: `Serialize does not support an array as the root input`.
# MessagePack is less compression-efficient.
# Protobuf requires a schema definition file and precompilation. Which is not practical in the case of a shared cache.
# lz4 is very unstable. Deviation in min-max time is very high.
# broatli encoding is very slow.

With this, we have only 2 candidates left: `defleat` and `gzip`. While `deflate` compression is slightly better, `gzip` shows much more stable deviations. The max values are much better for `gzip`, so let's pick it as the winner.



*Benchmark code*

{code:javascript}import { pack, unpack } from "msgpackr";
import lz4 from "lz4";
import zlib from "node:zlib";
// import { BSON } from "bson";

const sampleData = Array.from({ length: 30 }, (_, i) => ({
    cid: i + 16547,
    wd: [1, 4],
    cst: 1700000000,
    cend: 1700003600,
    pst: 300,
    pend: 1200,
}));

const jsonString = JSON.stringify(sampleData);
const jsonBuffer = Buffer.from(jsonString);

const withBench = (fn, iterations = 10000) => {
    const durations = new Array(iterations);
    for (let i = 0; i < iterations; i++) {
        const start = process.hrtime.bigint();
        fn();
        const end = process.hrtime.bigint();
        durations[i] = end - start;
    }
    return {
        min: Math.min(...durations.map(Number)),
        max: Math.max(...durations.map(Number)),
    };
};

const bufferToJSON = (buffer) => JSON.parse(buffer.toString());
const formatNumber = (number) => String(number ?? 0).padEnd(8, " ");

(async function benchmark() {
    console.log("Starting benchmark...\n");
    const start = performance.now();

    const jsonUnpackResults = withBench(() => JSON.parse(jsonString));
    const results = [
        ["JSON.strigify", jsonBuffer.length, 0, jsonUnpackResults],
    ];

    // MessagePack
    const packedMsgPack = pack(sampleData);
    const mpPackDuration = withBench(() => pack(sampleData));
    const mpUnpackDuration = withBench(() => unpack(packedMsgPack));
    results.push([
        "MessagePack",
        packedMsgPack.length,
        mpPackDuration,
        mpUnpackDuration,
    ]);

    // JSON + LZ4
    const compressedLZ4 = lz4.encode(jsonBuffer);
    const lz4PackDuration = withBench(() => lz4.encode(jsonBuffer));
    const lz4UpackDuration = withBench(() =>
        bufferToJSON(lz4.decode(compressedLZ4)),
    );
    results.push([
        "JSON + LZ4",
        compressedLZ4.length,
        lz4PackDuration,
        lz4UpackDuration,
    ]);

    // JSON + deflate
    const compressedZlib = zlib.deflateSync(jsonBuffer);
    const zlibPackDuration = withBench(() => zlib.deflateSync(jsonBuffer));
    const zlibUnpackDuration = withBench(() =>
        bufferToJSON(zlib.inflateSync(compressedZlib)),
    );
    results.push([
        "JSON + zlib.deflate",
        compressedZlib.length,
        zlibPackDuration,
        zlibUnpackDuration,
    ]);

    // JSON + gzip
    const gzipCompressed = zlib.gzipSync(jsonBuffer);
    const gzipPackDuration = withBench(() => zlib.gzipSync(jsonBuffer));
    const gzipUnpackDuration = withBench(() =>
        bufferToJSON(zlib.inflateSync(compressedZlib)),
    );
    results.push([
        "JSON + zlib.gzip",
        gzipCompressed.length,
        gzipPackDuration,
        gzipUnpackDuration,
    ]);

    // JSON + broatli
    const broatliCompressed = zlib.brotliCompressSync(jsonBuffer);
    const broatliPackDuration = withBench(() =>
        zlib.brotliCompressSync(jsonBuffer),
    );
    const broatliUnpackDuration = withBench(() =>
        bufferToJSON(zlib.brotliDecompressSync(broatliCompressed)),
    );
    results.push([
        "JSON + zlib.broatli",
        broatliCompressed.length,
        broatliPackDuration,
        broatliUnpackDuration,
    ]);

    // BSON
    // BSONError: serialize does not support an array as the root input
    // const startBson = performance.now();
    // const compressedBson = BSON.serialize(sampleData);
    // const endBson = performance.now();
    // results.push(["BSON", compressedBson.length, endBson - startBson]);

    const end = performance.now();
    console.log(`Benchmark finished. Duration: ${end - start} ms`);

    console.table(
        results.map(([method, size, packTime, unpackTime]) => ({
            Method: method,
            "Size (bytes)": size,
            "Pack time (ns)": `${formatNumber(packTime.min)} - ${formatNumber(packTime.max)}`,
            "Unpack time (ns)": `${formatNumber(unpackTime.min)} - ${formatNumber(unpackTime.max)}`,
        })),
    );
})();
{code}

